package com.preventminimapreset;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;

@ConfigGroup("preventMinimapReset")
public interface PreventMinimapResetConfig extends Config
{
	@ConfigItem(
			keyName = "rightClickResetZoom",
			name = "Allow right click to reset zoom",
			description = "When disabled, right-clicking the minimap will not reset the zoom level."
	)
	default boolean rightClickResetZoom()
	{
		return false;
	}
}

package com.preventminimapreset;

import com.google.inject.Provides;
import java.awt.event.MouseEvent;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.events.ClientTick;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.input.MouseListener;
import net.runelite.client.input.MouseManager;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;

@PluginDescriptor(
		name = "Prevent Minimap Reset",
		description = "Prevents the minimap zoom from being reset by right-clicking",
		tags = {"minimap", "zoom", "reset", "prevent"}
)
public class PreventMinimapResetPlugin extends Plugin
{
	@Inject
	private Client client;

	@Inject
	private PreventMinimapResetConfig config;

	@Inject
	private MouseManager mouseManager;

	/**
	 * Number of client ticks (~20ms each) to keep restoring the zoom after a right-click.
	 * The game engine doesn't always reset the zoom on the same tick as the click,
	 * so we re-apply the saved zoom for a short window (~200ms) to catch the delayed reset.
	 */
	private static final int RESTORE_TICKS = 10;

	private double lastKnownZoom = 0;
	private volatile boolean rightClickDetected = false;
	private volatile int rightClickX = -1;
	private volatile int rightClickY = -1;
	private double zoomToRestore = 0;
	private int restoreTicksRemaining = 0;

	private final MouseListener mouseListener = new MouseListener()
	{
		@Override
		public MouseEvent mousePressed(MouseEvent e)
		{
			if (e.getButton() == MouseEvent.BUTTON3)
			{
				rightClickX = e.getX();
				rightClickY = e.getY();
				rightClickDetected = true;
			}
			return e;
		}

		@Override
		public MouseEvent mouseReleased(MouseEvent e) { return e; }
		@Override
		public MouseEvent mouseClicked(MouseEvent e) { return e; }
		@Override
		public MouseEvent mouseEntered(MouseEvent e) { return e; }
		@Override
		public MouseEvent mouseExited(MouseEvent e) { return e; }
		@Override
		public MouseEvent mouseDragged(MouseEvent e) { return e; }
		@Override
		public MouseEvent mouseMoved(MouseEvent e) { return e; }
	};

	@Override
	protected void startUp() throws Exception
	{
		mouseManager.registerMouseListener(mouseListener);
	}

	@Override
	protected void shutDown() throws Exception
	{
		mouseManager.unregisterMouseListener(mouseListener);
		restoreTicksRemaining = 0;
		lastKnownZoom = 0;
	}

	@Subscribe
	public void onClientTick(ClientTick event)
	{
		if (config.rightClickResetZoom())
		{
			lastKnownZoom = 0;
			restoreTicksRemaining = 0;
			return;
		}

		double currentZoom = client.getMinimapZoom();

		if (rightClickDetected)
		{
			rightClickDetected = false;
			if (lastKnownZoom > 0 && isOverMinimap(rightClickX, rightClickY))
			{
				zoomToRestore = lastKnownZoom;
				restoreTicksRemaining = RESTORE_TICKS;
			}
		}

		if (restoreTicksRemaining > 0)
		{
			if (zoomToRestore > 0 && Math.abs(currentZoom - zoomToRestore) > 0.001)
			{
				client.setMinimapZoom(zoomToRestore);
				currentZoom = zoomToRestore;
			}
			restoreTicksRemaining--;
		}

		lastKnownZoom = currentZoom;
	}

	private boolean isOverMinimap(int x, int y)
	{
		return isPointOverWidget(x, y, InterfaceID.Toplevel.MINIMAP)
			|| isPointOverWidget(x, y, InterfaceID.ToplevelOsrsStretch.MINIMAP)
			|| isPointOverWidget(x, y, InterfaceID.ToplevelPreEoc.MINIMAP);
	}

	private boolean isPointOverWidget(int x, int y, int componentId)
	{
		Widget widget = client.getWidget(componentId);
		return widget != null && !widget.isHidden() && widget.getBounds().contains(x, y);
	}

	@Provides
	PreventMinimapResetConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(PreventMinimapResetConfig.class);
	}
}

package com.preventminimapreset;

import net.runelite.client.RuneLite;
import net.runelite.client.externalplugins.ExternalPluginManager;

public class PreventMinimapResetTest
{
	public static void main(String[] args) throws Exception
	{
		ExternalPluginManager.loadBuiltin(PreventMinimapResetPlugin.class);
		RuneLite.main(args);
	}
}
